import{_ as r,a0 as l,w as s,s as p,ao as d,I as a,x as e,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"肯特·貝克：改變人生的代碼整理魔法 | LCTT x X-CMD","titleTemplate":false,"description":"肯特·貝克：改變人生的代碼整理魔法 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"肯特·貝克：改變人生的代碼整理魔法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"肯特·貝克：改變人生的代碼整理魔法 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20170608 The Life-Changing Magic of Tidying Up Code","title":"肯特·貝克：改變人生的代碼整理魔法","tag":"201711","desc":""},"relativePath":"201711/20170608 The Life-Changing Magic of Tidying Up Code.md","filePath":"[post].md"}'),g={name:"201711/20170608 The Life-Changing Magic of Tidying Up Code.md"};function f(T,t,m,u,C,k){const o=l("Link");return s(),p("div",null,[t[13]||(t[13]=d('<h1 id="肯特·貝克-改變人生的代碼整理魔法" tabindex="-1">肯特·貝克：改變人生的代碼整理魔法 <a class="header-anchor" href="#肯特·貝克-改變人生的代碼整理魔法" aria-label="Permalink to “肯特·貝克：改變人生的代碼整理魔法”">​</a></h1><blockquote><p>本文作者<ruby>肯特·貝克<rt>Kent Beck</rt></ruby>，是最早研究軟件開發的模式和重構的人之一，是敏捷開發的開創者之一，更是極限編程和測試驅動開發的創始人，同時還是 Smalltalk 和 JUnit 的作者，對當今世界的軟件開發影響深遠。現在 Facebook 工作。</p></blockquote><p>本週我一直在整理 Facebook 代碼，而且我喜歡這個工作。我的職業生涯中已經整理了數千小時的代碼，我有一套使這種整理更加安全、有趣和高效的規則。</p><p>整理工作是通過一系列短小而安全的步驟進行的。事實上，規則一就是<strong>如果這很難，那就不要去做</strong>。我以前在晚上做填字遊戲。如果我卡住那就去睡覺，第二天晚上那些沒有發現的線索往往很容易發現。與其想要一心搞個大的，不如在遇到阻力的時候停下來。</p><p>整理會陷入這樣一種感覺：你錯失的要比你從一個個成功中獲得的更多（稍後會細説）。第二條規則是<strong>當你充滿活力時開始，當你累了時停下來</strong>。起來走走。如果還沒有恢復精神，那這一天的工作就算做完了。</p><p>只有在仔細追蹤其它變化的時候（我把它和最新的差異搞混了），整理工作才可以與開發同步進行。第三條規則是<strong>立即完成每個環節的工作</strong>。與功能開發所不同的是，功能開發只有在完成一大塊工作時才有意義，而整理是基於時間一點點完成的。</p><p>整理在任何步驟中都只需要付出不多的努力，所以我會在任何步驟遇到麻煩的時候放棄。所以，規則四是<strong>兩次失敗後恢復</strong>。如果我整理代碼，運行測試，並遇到測試失敗，那麼我會立即修復它。如果我修復失敗，我會立即恢復到上次已知最好的狀態。</p><p>即便沒有閃亮的新設計的願景，整理也是有用的。不過，有時候我想看看事情會如何發展，所以第五條就是<strong>實踐</strong>。執行一系列的整理和還原。第二次將更快，你會更加熟悉避免哪些坑。</p><p>只有在附帶損害的風險較低，審查整理變化的成本也較低的時候整理才有用。規則六是<strong>隔離整理</strong>。如果你錯過了在編寫代碼中途整理的機會，那麼接下來可能很困難。要麼完成並接着整理，要麼還原、整理並進行修改。</p><p>試試這些。將臨時申明的變量移動到它第一次使用的位置，簡化布爾表達式（<code>return expression == True</code>？），提取一個 helper，將邏輯或狀態的範圍縮小到實際使用的位置。</p><h3 id="規則" tabindex="-1">規則 <a class="header-anchor" href="#規則" aria-label="Permalink to “規則”">​</a></h3><ul><li>規則一、 如果這很難，那就不要去做</li><li>規則二、 當你充滿活力時開始，當你累了時停下來</li><li>規則三、 立即完成每個環節工作</li><li>規則四、 兩次失敗後恢復</li><li>規則五、 實踐</li><li>規則六、 隔離整理</li></ul><h3 id="尾聲" tabindex="-1">尾聲 <a class="header-anchor" href="#尾聲" aria-label="Permalink to “尾聲”">​</a></h3><p>我通過嚴格地整理改變了架構、提取了框架。這種方式可以安全地做出重大改變。我認為這是因為，雖然每次整理的成本是不變的，但回報是指數級的，但我需要數據和模型來解釋這個假説。</p><hr>',15)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),i(o,{href:"https://www.facebook.com/notes/kent-beck/the-life-changing-magic-of-tidying-up-code/1544047022294823/"},{default:n(()=>[...t[0]||(t[0]=[e("https://www.facebook.com/notes/kent-beck/the-life-changing-magic-of-tidying-up-code/1544047022294823/",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=e("作者：",-1)),i(o,{href:"https://www.facebook.com/kentlbeck"},{default:n(()=>[...t[2]||(t[2]=[e("KENT BECK",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),i(o,{href:"https://github.com/geekpi"},{default:n(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=e("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const L=r(g,[["render",f]]);export{x as __pageData,L as default};
